import React from 'react';
import Row from "../../elements/base/layouts/row/Row";

const SeparatedRow = ({
                          children,
                          horizontalArrangement = 'start', // Horizontal alignment of items (default 'start')
                          verticalAlignment = 'start', // Vertical alignment of items (default 'start')
                          spaceBy = 0, // Spacing between items (in pixels)
                          style = {}, // Additional custom styles
                          separator,
                      }) => {
    return <Row
        horizontalArrangement={horizontalArrangement}
        verticalAlignment={verticalAlignment}
        spaceBy={spaceBy}
        style={style}
    >
        {React.Children.toArray(children).reduce((acc, child, index, array) => {
            acc.push(child);
            if (index < array.length - 1) {
                acc.push(separator);
            }
            return acc;
        }, [])}
    </Row>
};

export default SeparatedRow;
