import React, {useState} from 'react';


export const ipaButtonStyle = {
    unvoiced: {
        backgroundColor: "#3D845F",
        borderColor: "#689E7F",
        backgroundHoveredColor: "#689E7F",
        backgroundPressedColor: "#2d6146"
    },
    voiced: {
        backgroundColor: "#3F3D84",
        borderColor: "#69689E",
        backgroundHoveredColor: "#69689E",
        backgroundPressedColor: "#2d2b5e",
    },
    short: {
        backgroundColor: "#BE8653",
        borderColor: "#E6B588",
        backgroundHoveredColor: "#E6B588",
        backgroundPressedColor: "#976a42",
    },
    long: {
        backgroundColor: "#C97D39",
        borderColor: "#D0AA88",
        backgroundHoveredColor: "#D0AA88",
        backgroundPressedColor: "#a86930",
    },
    dipthongs: {
        backgroundColor: "#A46732",
        borderColor: "#D59A65",
        backgroundHoveredColor: "#D59A65",
        backgroundPressedColor: "#835328",
    },
    special: {
        backgroundColor: "#565556",
        borderColor: "#747474",
        backgroundHoveredColor: "#747474",
        backgroundPressedColor: "#3e3d3e",
    },
};

const IpaKeyButton = ({
                          label,
                          onClick,
                          buttonStyle = ipaButtonStyle.special,
                          borderWidth = 2,
                          borderRadius = 10,
                          textColor = '#fff',
                          fontSize = 16,
                          width = 'auto',
                          height = 'auto',
                          style = {}
                      }) => {
    const [isHovered, setIsHovered] = useState(false);
    const [isPressed, setIsPressed] = useState(false);

    let backgroundColor = buttonStyle.backgroundColor;

    if (isPressed) {
        backgroundColor = buttonStyle.backgroundPressedColor;
    } else if (isHovered) {
        backgroundColor = buttonStyle.backgroundHoveredColor;
    }

    const cssStyle = {
        backgroundColor: backgroundColor,
        borderColor: buttonStyle.borderColor,
        borderWidth,
        borderStyle: 'solid',
        borderRadius,
        color: textColor,
        fontSize,
        cursor: 'pointer',
        outline: 'none',
        width,
        height,
        ...style
    };

    return (
        <button
            style={cssStyle}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            onMouseDown={(event) => {
                setIsPressed(true);
                onClick(event, label);
            }
            }
            onMouseUp={() => setIsPressed(false)}
        >
            {label}
        </button>
    );
};

export default IpaKeyButton;