import React, {useState} from 'react';
import './AddButton.css';
import AddMenu from "./menu/MenuButton";

export const ButtonTypeClicked = {
    ADD_TEXT: "ADD_TEXT",
    ADD_INTONATION: "ADD_INTONATION",
    ADD_PAUSE: "ADD_PAUSE",
};

const AddButton = ({onClick}) => {
    const [isAddFocused, setIsAddFocused] = useState(false);
    const [menuVisible, setMenuVisible] = useState(false);

    return (
        <button
            className="add-btn"
            onMouseEnter={() => setIsAddFocused(true)}
            onMouseLeave={() => setIsAddFocused(false)}
        >
            +
            {(isAddFocused || menuVisible) && (
                <AddMenu onClick={onClick} onMouseFocused={(isFocused) => setMenuVisible(isFocused)}/>
            )}
        </button>
    );
}

export default AddButton;
