import React from 'react';

const Spacer = ({size = 0, direction = 'vertical', weight = 0}) => {
    const spacerStyle =
        direction === 'vertical'
            ? weight > 0
                ? {flexGrow: weight} // Use flex-grow for proportional space if weight is provided
                : {height: size ? `${size}px` : 'auto'} // Use fixed size if no weight is provided
            : weight > 0
                ? {flexGrow: weight} // Use flex-grow for horizontal direction
                : {width: size ? `${size}px` : 'auto'}; // Use fixed size for horizontal direction

    return <div style={spacerStyle}/>;
};

export default Spacer;
