import React, {useState} from 'react';
import AddButton, {ButtonTypeClicked as ButtonTypes} from "./addBtn/AddButton";
import WordView from "./word/WordView";
import PauseDialog from "./pause/dialog/PauseDialog";
import IntonationView from "./intonation/IntonationView";
import PauseView from "./pause/PauseView";
import IntonationDialog from "./intonation/dialog/IntonationDialog";
import './EditorView.css'


export const ElementType = {
    ADD_BTN: "ADD_BTN",
    TEXT: "TEXT",
    INTONATION: "INTONATION",
    PAUSE: "PAUSE",
};

class EditorComponent {
    id = EditorComponent._id++

    static _id = 0
}

class AddBtn extends EditorComponent {
    type = ElementType.ADD_BTN;
}

class Text extends EditorComponent {
    type = ElementType.TEXT;

    constructor(text = "", pronunciation = "") {
        super();
        this.text = text
        this.pronunciation = pronunciation
    }
}


class Intonation extends EditorComponent {
    type = ElementType.INTONATION;

    constructor(intonation) {
        super();
        this.intonation = intonation
    }
}

class Pause extends EditorComponent {
    type = ElementType.PAUSE;

    constructor(pause) {
        super();
        this.pause = pause
    }
}

const EditorView = ({style}) => {
    const [elements, setElements] = useState([new AddBtn()]);
    const [requestIntonationAt, setRequestIntonationAt] = useState(-1);
    const [updateIntonation, setUpdateIntonation] = useState(undefined);
    const [requestPauseAt, setRequestPauseAt] = useState(-1);
    const [updatePause, setUpdatePause] = useState(undefined);

    const addComponentWithAddBtnAt = (index, component) => {
        const newElements = [...elements];
        newElements.splice(index, 0, component, new AddBtn());
        setElements(newElements);
    }

    const remoteComponentWithAddBtnAt = (index) => {
        const newElements = [...elements];
        newElements.splice(index, 2);
        setElements(newElements);
    }

    const addElement = (type, index) => {
        const insertionIndex = index + 1;
        switch (type) {
            case ButtonTypes.ADD_TEXT: {
                addComponentWithAddBtnAt(insertionIndex, new Text());
                break
            }
            case ButtonTypes.ADD_INTONATION: {
                setRequestIntonationAt(index);
                break
            }
            case ButtonTypes.ADD_PAUSE: {
                setRequestPauseAt(index);
                break
            }
        }
    };

    const addIntonation = (value) => {
        const insertionIndex = requestIntonationAt + 1;
        addComponentWithAddBtnAt(insertionIndex, new Intonation(value));
        setRequestIntonationAt(-1);
    }

    const addPause = (value) => {
        const insertionIndex = requestPauseAt + 1;
        addComponentWithAddBtnAt(insertionIndex, new Pause(value));
        setRequestPauseAt(-1);
    }

    return <div className="editor-view" style={style}>
        {elements.map((item, index) => {
            switch (item.type) {
                case ElementType.ADD_BTN: {
                    return <AddButton
                        key={item.id}
                        onClick={(type) => addElement(type, index)}
                    />
                }
                case ElementType.TEXT: {
                    return <WordView
                        key={item.id}
                        data={item}
                        onRemove={() => remoteComponentWithAddBtnAt(index)}
                    />
                }
                case ElementType.INTONATION: {
                    return <IntonationView
                        key={item.id}
                        data={item}
                        onClick={() => setUpdateIntonation(item)}
                        onRemove={() => remoteComponentWithAddBtnAt(index)}
                    />
                }
                case ElementType.PAUSE: {
                    return <PauseView
                        key={item.id}
                        data={item}
                        onClick={() => setUpdatePause(item)}
                        onRemove={() => remoteComponentWithAddBtnAt(index)}
                    />
                }
            }
        })}

        {requestIntonationAt !== -1 && <IntonationDialog
            onSelect={(event, value) => addIntonation(value)}
            onCloseClick={() => setRequestIntonationAt(-1)}
        />}

        {updateIntonation && <IntonationDialog
            data={updateIntonation}
            onSelect={(event, value) => {
                updateIntonation.intonation = value;
                setUpdateIntonation(undefined)
            }}
            onCloseClick={() => setUpdateIntonation(undefined)}
        />}

        {requestPauseAt !== -1 && <PauseDialog
            onSelect={(event, value) => addPause(value)}
            onCloseClick={() => setRequestPauseAt(-1)}
        />}

        {updatePause && <PauseDialog
            data={updatePause}
            onSelect={(event, value) => {
                updatePause.pause = value;
                setUpdatePause(undefined)
            }
            }
            onCloseClick={() => setUpdatePause(undefined)}
        />}

    </div>
};

export default EditorView;
