import React, {useEffect, useState} from 'react';
import './WordView.css'
import ContentEditable from "../../../elements/base/input/contenteditable/ContentEditable";
import ElementContainer from "../elementcontainer/ElementContainer";

const WordView = ({data, onRemove}) => {
    const [isHovered, setIsHovered] = useState(false);
    const [isTooltipFocused, setIsTooltipFocused] = useState(false);
    const [text, setText] = useState(data.text);
    const [tooltip, setTooltip] = useState(data.pronunciation);

    useEffect(() => {
        data.text = text;
        data.tooltip = tooltip;
    }, [text, tooltip]);

    return (
        <ElementContainer
            className="word-view-container"
            onRemove={onRemove}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
        >
            <ContentEditable
                className="word-input"
                value={text}
                onChange={setText}
                placeholder={"word"}
                style={{
                    width: '100%',
                    height: '100%'
                }}/>

            <ContentEditable
                className="tooltip"
                value={tooltip}
                onChange={setTooltip}
                placeholder={"pronunciation"}
                onFocus={() => setIsTooltipFocused(true)}
                onBlur={() => setIsTooltipFocused(false)}
                style={{display: isHovered || isTooltipFocused ? "block" : "none"}}
            />
        </ElementContainer>
        // <div
        //         className="word"
        //         onMouseEnter={() => setIsHovered(true)}
        //         onMouseLeave={() => setIsHovered(false)}
        //     >
        //         <ContentEditable
        //             className="word-input"
        //             value={text}
        //             onChange={setText}
        //             style={{
        //                 width: '100%',
        //                 height: '100%'
        //             }}/>
        //
        //         <ContentEditable
        //             className="tooltip"
        //             value={tooltip}
        //             onChange={setTooltip}
        //             onFocus={() => setIsTooltipFocused(true)}
        //             onBlur={() => setIsTooltipFocused(false)}
        //             style={{display: isHovered || isTooltipFocused ? "block" : "none"}}
        //         />
        //         <button className="remove-btn" onClick={onRemove}>×</button>
        //     </div>
    );
};

export default WordView;
