import React from 'react';
import './PrimaryTextField.css';

const PrimaryTextField = ({value, onChange, onFocusChange, placeholder, icon, type = 'text'}) => {
    const handleFocus = () => {
        onFocusChange(true);
    };
    const handleBlur = () => {
        onFocusChange(false);
    };

    return (
        <div className="primary-textfield">
            {icon && <img src={icon} alt="icon" className="primary-textfield-icon"/>}
            <input
                className="primary-textfield-input"
                type={type}
                value={value}
                onChange={onChange}
                onFocus={handleFocus}
                onBlur={handleBlur}
                placeholder={placeholder}
            />
        </div>
    );
};

export default PrimaryTextField;