import React from 'react';
import {ipaButtonStyle} from "./IpaKeyButton";


const IpaKeyButtonDescription = ({
                          label,
                          buttonStyle = ipaButtonStyle.special,
                          borderWidth = 2,
                          borderRadius = 10,
                          textColor = '#fff',
                          fontSize = 18,
                          style = {}
                      }) => {
    const cssStyle = {
        backgroundColor: buttonStyle.backgroundColor,
        borderColor: buttonStyle.borderColor,
        borderWidth,
        borderStyle: 'solid',
        borderRadius,
        color: textColor,
        fontSize,
        cursor: 'default',
        outline: 'none',
        width: 120,
        height: 24,
        textAlign: "center",
        alignContent: "center",
        ...style
    };

    return (
        <div style={cssStyle}>
            {label}
        </div>
    );
};

export default IpaKeyButtonDescription;