import React, {useState} from 'react';
import Column from "../elements/base/layouts/column/Column";
import Row from "../elements/base/layouts/row/Row";
import BackButton from "../elements/custom/buttons/back/BackButton";
import PrimaryButton from "../elements/base/buttons/PrimaryButton";
import Spacer from "../elements/base/spacer/Spacer";
import PrimaryTextField from "../elements/base/input/textfield/PrimaryTextField";
import IpaKeyboard from "./elements/keyboard/IpaKeyboard";
import SeparatedRow from "./elements/SeparatedRow";
import TextButton from "../elements/base/buttons/text/TextButton";
import EditorView from "./editor/EditorView";

const EditShadowingScreen = () => {
    const onSaveClicked = () => {
        console.log('Button clicked!');
    };
    const onBackClicked = () => {
        console.log('Button clicked!');
    };

    const [text, setText] = useState("Untitled recording");

    const onValueChange = (e) => {
        setText(e.target.value);
    };

    const onFocusChange = (hasFocus) => {
        if (!hasFocus && text.length === 0) {
            setText("Untitled recording");
        }
    };

    function appendSymbol(symbol) {
        if (document.activeElement) {
            document.execCommand("insertHTML", false, symbol);
        }
    }

    return (
        <Column
            horizontalAlignment={"center"}
            style={{
                padding: "12px",
                height: "100%",
                boxSizing: 'border-box'
            }}>
            <Row horizontalArrangement="spaceBetween" style={{width: "100%"}}>
                <Row spaceBy={24}>
                    <BackButton onClick={onBackClicked}/>
                    <PrimaryTextField
                        value={text}
                        onChange={onValueChange}
                        onFocusChange={onFocusChange}
                        icon="save.svg"
                    />
                </Row>

                <PrimaryButton
                    icon="save.svg"
                    text="Save changes"
                    onClick={onSaveClicked}
                />
            </Row>

            <Spacer size={12}/>

            <Row style={{width: "100%"}}>
                <SeparatedRow
                    separator={<img src="divider.svg" alt="icon"/>}
                    style={{
                        background: "#3F3F3F",
                        padding: "8px 12px",
                        borderRadius: "30px"
                    }}
                >
                    <TextButton
                        icon="FileText.svg"
                        text="Upload srt file"
                    />
                    <TextButton
                        icon="FileAudio.svg"
                        text="Upload audio file"
                    />
                    <TextButton
                        icon="Intersect.svg"
                        text="Merge"
                    />
                    <TextButton
                        text="back forward"
                    />
                </SeparatedRow>

                <Spacer weight={1}/>

                <SeparatedRow
                    separator={<img src="divider.svg" alt="icon"/>}
                    style={{
                        background: "#3F3F3F",
                        padding: "8px 12px",
                        borderRadius: "30px"
                    }}
                >
                    <TextButton
                        text="play controlls"
                    />
                    <TextButton
                        text="player..........................................."
                    />
                </SeparatedRow>

                <Spacer size={24} direction={"horizontal"}/>

                <Row
                    spaceBy={6}
                    style={{
                        background: "#3F3F3F",
                        padding: "8px 12px",
                        borderRadius: "30px"
                    }}
                >
                    <TextButton
                        text="Dificulty selector"
                    />
                </Row>
            </Row>

            <EditorView
                style={{
                    width: "100%",
                    height: "100%",
                    margin: "32px 32px",
                    boxSizing: 'border-box',
                }}/>

            <Spacer weight={1}/>

            <IpaKeyboard onKeyClick={(event, key) => {
                event.preventDefault();
                appendSymbol(key);
            }
            }/>
        </Column>
    );
};

export default EditShadowingScreen;