import React from 'react';

// Mapping Jetpack Compose-like names to Flexbox values
export const alignmentMap = {
    start: 'flex-start',
    end: 'flex-end',
    center: 'center',
    stretch: 'stretch', // added stretch as an option for horizontal alignment
};

export const arrangementMap = {
    start: 'flex-start',
    end: 'flex-end',
    center: 'center',
    spaceBetween: 'space-between',
    spaceAround: 'space-around',
    spaceEvenly: 'space-evenly',
};

const Row = ({
                 children,
                 horizontalArrangement = 'start', // Horizontal alignment of items (default 'start')
                 verticalAlignment = 'start', // Vertical alignment of items (default 'start')
                 spaceBy = 0, // Spacing between items (in pixels)
                 style = {}, // Additional custom styles
             }) => {
    // Apply the alignment and arrangement maps
    const rowStyle = {
        display: 'flex',
        flexDirection: 'row', // Arrange items horizontally
        alignItems: alignmentMap[verticalAlignment] || 'flex-start', // Map vertical alignment
        justifyContent: arrangementMap[horizontalArrangement] || 'flex-start', // Map horizontal alignment
        gap: `${spaceBy}px`,  // Space between items (spacing in Jetpack Compose)
        ...style,  // Apply any additional custom styles
    };

    return <div style={rowStyle}>{children}</div>;
};

export default Row;
