import React from 'react';
import './AddMenu.css';
import {ButtonTypeClicked as ButtonType} from "../AddButton";

const MenuButton = ({label, type, onClick}) => {
    return <button className="add-menu-item" onClick={() => onClick(type)}>{label}</button>;
}

const AddMenu = ({onClick, onMouseFocused}) => {
    return (
        <div className="add-menu"
             onMouseEnter={() => onMouseFocused(true)}
             onMouseLeave={() => onMouseFocused(false)}>
            <MenuButton label={"Add text"} type={ButtonType.ADD_TEXT} onClick={onClick}/>
            <MenuButton label={"Add intonation"} type={ButtonType.ADD_INTONATION} onClick={onClick}/>
            <MenuButton label={"Add pause"} type={ButtonType.ADD_PAUSE} onClick={onClick}/>
        </div>
    );
}

export default AddMenu;