import React from 'react';
import './IntonationDialog.css';
import Row from "../../../../elements/base/layouts/row/Row";
import IpaKeyButton from "../../../elements/keyboard/IpaKeyButton";
import Column from "../../../../elements/base/layouts/column/Column";
import Spacer from "../../../../elements/base/spacer/Spacer";

const intonationSymbols = ["↘", "↗", "↘↘", "↗↗", "↘↗", "↗↘", "↘↘↗", "↗↗↘"]

const IntonationDialog = ({onSelect, onCloseClick}) => {
    return <div className="dialog-overlay">
        <Column className="dialog-box" spaceBy={12}>
            <Row style={{width:'100%'}}>
                <h3 className={"dialog-box-header"}>Select an intonation:</h3>
                <Spacer weight={1} direction={"horizontal"}/>
                <button className="close-btn" id="closeDialogBtn" onClick={onCloseClick}>×</button>
            </Row>

            <Row horizontalArrangement={"center"} spaceBy={6} style={{width: "100%"}}>
                {intonationSymbols.map((item, index) => {
                    return <IpaKeyButton
                        label={item}
                        onClick={onSelect}
                        key={index}
                        textColor="#fff"
                        fontSize={18}
                        borderWidth={2}
                        borderRadius={10}
                        width={40}
                        height={40}/>;
                })}
            </Row>
        </Column>
    </div>
};

export default IntonationDialog;
