import React, {useLayoutEffect, useRef, useState} from "react";
import './ContentEditable.css'

const ContentEditable = ({className, value, onChange, placeholder, onFocus, onBlur, style}) => {
    const [offset, setOffset] = useState()
    const textRef = useRef()

    useLayoutEffect(() => {
        if (offset !== undefined) {
            const newRange = document.createRange()
            if (textRef.current.childNodes.length === 0) return;
            newRange.setStart(textRef.current.childNodes[0], offset)
            const selection = document.getSelection()
            selection.removeAllRanges()
            selection.addRange(newRange)
        }
    })

    function inputHandler(ev) {
        const range = document.getSelection().getRangeAt(0)
        setOffset(range.startOffset)
        onChange(ev.target.innerHTML)
    }

    function focusHandler() {
        setTimeout(() => {
            onFocus && onFocus()
            const selection = document.getSelection()
            if (selection.rangeCount > 0) {
                const range = selection.getRangeAt(0)
                setOffset(range.startOffset)
            }
        }, 0)
    }

    function blurHandler() {
        setOffset(undefined)
        onBlur && onBlur()
    }

    function clickHandler() {
        if (offset !== undefined) {
            const selection = document.getSelection()
            if (selection.rangeCount > 0) {
                const range = selection.getRangeAt(0)
                setOffset(range.startOffset)
            }
        }
    }

    return (
        <div
            className={className}
            contentEditable
            suppressContentEditableWarning
            onInput={inputHandler}
            onFocus={focusHandler}
            onBlur={blurHandler}
            onClick={clickHandler}
            placeholder={placeholder}
            dangerouslySetInnerHTML={{__html: value.replace(/<br\s*\/?>/gi, "")}}
            ref={textRef}
            style={style}
        />
    )
}

export default ContentEditable;