import React from 'react';

// Mapping Jetpack Compose-like names to Flexbox values
const alignmentMap = {
    start: 'flex-start',
    end: 'flex-end',
    center: 'center',
    stretch: 'stretch', // added stretch as an option for horizontal alignment
};

const arrangementMap = {
    start: 'flex-start',
    end: 'flex-end',
    center: 'center',
    spaceBetween: 'space-between',
    spaceAround: 'space-around',
    spaceEvenly: 'space-evenly',
};

const Column = ({
                    className,
                    children,
                    horizontalAlignment = 'start',  // Default to 'start'
                    verticalArrangement = 'start',  // Default to 'start'
                    spaceBy = 0, // Spacing between items
                    style = {},  // Additional custom styles
                }) => {
    // Apply the alignment and arrangement maps
    const columnStyle = {
        display: 'flex',
        flexDirection: 'column',  // Stack items vertically
        alignItems: arrangementMap[horizontalAlignment] || 'flex-start',  // Map horizontal alignment
        justifyContent: alignmentMap[verticalArrangement] || 'flex-start',  // Map vertical arrangement
        gap: `${spaceBy}px`,  // Space between items (spacing in Jetpack Compose)
        ...style,  // Apply any additional styles
    };

    return <div className={className} style={columnStyle}>{children}</div>;
};

export default Column;
