import React from 'react';

const arrangementMap = {
    start: 'flex-start',
    end: 'flex-end',
    center: 'center',
    spaceBetween: 'space-between',
    spaceAround: 'space-around',
    spaceEvenly: 'space-evenly',
};

// VerticalGrid component
const HorizontalGrid = ({
                  children,
                  horizontalArrangement = 'start', // Horizontal arrangement of items (default 'start')
                  verticalArrangement = 'start', // Vertical arrangement of items (default 'start')
                  columns = 3, // Number of columns in the grid (default 3)
                  spaceByVertically = 10, // Vertical space between items (in pixels)
                  spaceByHorizontally = 10, // Horizontal space between items (in pixels)
                  style = {}, // Additional custom styles
              }) => {
    // Apply the alignment and arrangement maps
    const gridStyle = {
        display: 'grid',
        gridTemplateColumns: `repeat(${columns}, max-content)`, // Create columns in grid
        gap: `${spaceByVertically}px ${spaceByHorizontally}px`, // Vertical and horizontal space between grid items
        justifyItems: arrangementMap[horizontalArrangement] || 'flex-start', // Horizontal arrangement
        alignItems: arrangementMap[verticalArrangement] || 'flex-start', // Vertical arrangement
        ...style, // Apply any additional custom styles
    };

    return <div style={gridStyle}>{children}</div>;
};

export default HorizontalGrid;
