import React from 'react';
import clsx from "clsx";
import './ElementContainer.css'

const ElementContainer = ({className, children, onClick, onMouseEnter, onMouseLeave, onRemove}) => {
    return (
        <div className={clsx("element-container", className)}
             onClick={onClick}
             onMouseEnter={onMouseEnter}
             onMouseLeave={onMouseLeave}
        >
            {children}
            <button className="element-container-remove-btn" onClick={onRemove}>×</button>
        </div>
    );
};

export default ElementContainer;
